#!/usr/bin/env bash
# Fetch and compile tree-sitter grammar fixtures for integration tests.
#
# Grammar revisions and URLs are read from each language's shipped data file,
# runtime/scheme/languages/<name>.scm (generated by scripts/sync-grammars.py from
# helix-pin.scm). To use a different grammar version, update helix-pin.scm and
# re-run sync-grammars.py.
#
# Idempotent: skips clone if the dir already exists and is at the correct rev, skips
# compile if the shared library is newer than the grammar source. Run once per
# machine and after any helix-pin bump that changes those files.
#
# Compiled artifacts go into tests/fixtures/grammars/ (gitignored). Every
# grammar's queries/ end up at tests/fixtures/grammars/<name>/queries/,
# regardless of whether the grammar lives at the root of its clone or in
# a monorepo subpath — test code can assume a uniform layout and never
# needs to read a language's data file for subpaths.
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
FIXTURES="$REPO_ROOT/tests/fixtures/grammars"
LANGUAGES_DIR="$REPO_ROOT/runtime/scheme/languages"
mkdir -p "$FIXTURES"

MANIFEST="$REPO_ROOT/Cargo.toml"
cargo build --locked --manifest-path "$MANIFEST" -p hume-grammar-build
TARGET_DIR="$(cargo metadata --format-version 1 --no-deps --manifest-path "$MANIFEST" \
  | python3 -c 'import json,sys; print(json.load(sys.stdin)["target_directory"])')"
GRAMMAR_BUILD="$TARGET_DIR/debug/hume-grammar-build"
case "$(uname -s)" in
  Darwin)               EXT="dylib" ;;
  MINGW*|MSYS*|CYGWIN*) EXT="dll"; GRAMMAR_BUILD="$GRAMMAR_BUILD.exe" ;;
  *)                    EXT="so"    ;;
esac

compile_grammar() {
  local name="$1"
  local src_dir="$2"
  local out_dir="$3"
  local out="$out_dir/parser.$EXT"

  if [[ -f "$out" && "$out" -nt "$src_dir/src/parser.c" ]]; then
    echo "  $name: up to date ($out)"
    return
  fi

  echo "  $name: compiling..."
  mkdir -p "$out_dir"
  "$GRAMMAR_BUILD" -o "$out" "$src_dir"
  echo "  $name: built $out"
}

# A language's data file holds its grammar on one line,
# (grammar "url" "rev" "symbol" "subpath"), matched whole: any other shape
# is an error rather than a field read from the wrong position.
# `subpath` is the directory within the cloned repo holding the grammar's
# `src/`, empty for the repo root; monorepos like tree-sitter-markdown hold
# multiple grammars (tree-sitter-markdown, tree-sitter-markdown-inline) as
# subdirectories of one clone.
fetch_grammar() {
  local name="$1"
  local data="$LANGUAGES_DIR/$name.scm"
  local entry='^[[:space:]]*\(?\(grammar "([^"]*)" "([^"]*)" "[^"]*" "([^"]*)"\)\)?$'
  local line repo rev subpath
  line=$(grep -F '(grammar "' "$data" 2>/dev/null || true)

  if [[ ! "$line" =~ $entry || -z "${BASH_REMATCH[1]}" || -z "${BASH_REMATCH[2]}" ]]; then
    echo "error: no (grammar \"url\" \"rev\" \"symbol\" \"subpath\") line for language '$name' in $data" >&2
    exit 1
  fi
  repo="${BASH_REMATCH[1]}"
  rev="${BASH_REMATCH[2]}"
  subpath="${BASH_REMATCH[3]}"

  local target="$FIXTURES/$name"

  echo "$name (${rev:0:12}):"
  if [[ ! -d "$target" ]]; then
    echo "  cloning..."
    git clone --filter=blob:none --quiet "$repo" "$target"
    git -C "$target" checkout --quiet --force "$rev"
  else
    local current
    current="$(git -C "$target" rev-parse HEAD)"
    if [[ "$current" != "$rev" ]]; then
      git -C "$target" fetch --quiet
      git -C "$target" checkout --quiet --force "$rev"
    fi
  fi

  local src_dir="$target"
  if [[ -n "$subpath" ]]; then
    src_dir="$target/$subpath"
  fi
  compile_grammar "$name" "$src_dir" "$target"

  # Normalize monorepo grammars (markdown, markdown.inline) so their
  # queries/ live at the fixture root like every other grammar's — copy
  # (not symlink, for Git Bash/Windows) so test code never needs to know
  # about `subpath`; that knowledge stays only in this script.
  if [[ -n "$subpath" && -d "$src_dir/queries" ]]; then
    rm -rf "$target/queries"
    cp -R "$src_dir/queries" "$target/queries"
  fi
}

HELIX_PIN="$(grep -v '^;' "$REPO_ROOT/runtime/scheme/helix-pin.scm" | tr -d '"[:space:]')"

# Fetch `helix_path`, relative to the Helix repository root at the pin, to
# `out` beside `name`'s grammar, unless it is already there. Best-effort: a
# file Helix does not have is skipped.
fetch_helix_file() {
  local name="$1"
  local helix_path="$2"
  local out="$3"
  if [[ -f "$out" ]]; then
    echo "  $name: $(basename "$out") up to date"
    return
  fi
  local url="https://raw.githubusercontent.com/helix-editor/helix/$HELIX_PIN/$helix_path"
  if curl -fsSL -o "$out" "$url"; then
    echo "  $name: fetched $(basename "$out")"
  else
    rm -f "$out"
    echo "  $name: no $helix_path on Helix (skipped)"
  fi
}

# Fetch a *Helix-maintained* query file for `name` — distinct from (and can
# differ from!) the grammar's own bundled queries/<file>. PLUM installs the
# Helix version, so tests need it too — a test fixture built from the
# grammar-bundled file instead would validate a query PLUM never actually
# installs. Best-effort: not every grammar has every query file.
fetch_helix_query() {
  local name="$1"
  local file="$2"
  fetch_helix_file "$name" "runtime/queries/$name/$file" "$FIXTURES/$name/helix-$file"
}

# Fetch Helix's indent test corpus file `file` (tests/indent/<file> at the
# pin) to helix-indent-corpus.<ext> beside `name`'s grammar. Helix's CI checks
# its indents.scm against these files, so they are the expected indentation
# for the queries fetched above. Best-effort, like fetch_helix_query.
fetch_helix_indent_corpus() {
  local name="$1"
  local file="$2"
  fetch_helix_file "$name" "tests/indent/$file" "$FIXTURES/$name/helix-indent-corpus.${file##*.}"
}

echo "Fetching tree-sitter grammar fixtures..."
fetch_grammar "rust"
fetch_grammar "json"
fetch_grammar "markdown"
fetch_grammar "markdown.inline"
fetch_grammar "python"
fetch_grammar "c"
fetch_grammar "html"
fetch_grammar "yaml"
fetch_helix_query "markdown" "injections.scm"
# rust/textobjects.scm has no `; inherits:` header, so a plain fetch is
# complete — a language whose file inherits would need PLUM's resolver.
fetch_helix_query "rust" "textobjects.scm"
fetch_helix_query "html" "textobjects.scm"
fetch_helix_query "rust" "injections.scm"
# None of these four indents.scm files has an `; inherits:` header.
fetch_helix_query "rust" "indents.scm"
fetch_helix_query "json" "indents.scm"
fetch_helix_query "python" "indents.scm"
fetch_helix_query "c" "indents.scm"
fetch_helix_indent_corpus "rust" "rust.rs"
fetch_helix_indent_corpus "json" "json.json"
fetch_helix_indent_corpus "python" "python.py"
fetch_helix_indent_corpus "c" "c.c"
echo "Done."
